import {
    Box, Heading, Text, Input, Button, VStack, HStack, Spinner
  } from '@chakra-ui/react'
  import { Alert } from '@chakra-ui/alert'
  import { Divider } from '@chakra-ui/layout'
  import { List, ListItem } from '@chakra-ui/list'
  import { useEffect, useState } from 'react'
  
  export default function Home() {
    const [salesReps, setSalesReps] = useState([])
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState(null)
    const [question, setQuestion] = useState('')
    const [aiResponse, setAIResponse] = useState('')
  
    useEffect(() => {
      fetch('http://localhost:8000/api/sales-reps')
        .then(res => {
          if (!res.ok) throw new Error('Failed to fetch data')
          return res.json()
        })
        .then(setSalesReps)
        .catch(err => setError(err.message))
        .finally(() => setLoading(false))
    }, [])
  
    const handleAskAI = async () => {
      const res = await fetch('http://localhost:8000/api/ai', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question })
      })
      const data = await res.json()
      setAIResponse(data.response)
    }
  
    return (
      <Box maxW="1000px" mx="auto" p={6}>
        <Heading mb={6} textAlign="center">Sales Dashboard</Heading>
  
        {/* AI Section */}
        <Box bg="gray.100" p={4} borderRadius="md" mb={6}>
          <Text fontWeight="bold" mb={2}>Ask the AI</Text>
          <HStack>
            <Input
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="Ask something about sales..."
            />
            <Button colorScheme="blue" onClick={handleAskAI}>Ask</Button>
          </HStack>
          {aiResponse && (
            <Text mt={3} fontStyle="italic">AI: {aiResponse}</Text>
          )}
        </Box>
  
        {/* Data Section */}
        {loading ? (
          <Spinner size="xl" thickness="4px" />
        ) : error ? (
          <Alert status="error" px={4} py={2} borderRadius="md">
            <Text fontWeight="bold" mr={2}>⚠️</Text>
            <Text>{error}</Text>
          </Alert>
        ) : (
          <VStack spacing={6} align="stretch">
            {salesReps.map((rep, index) => (
              <Box key={index} p={5} shadow="md" borderWidth="1px" borderRadius="md">
                <Heading fontSize="xl">{rep.name}</Heading>
                <Text color="gray.500" mb={2}>{rep.role} - {rep.region}</Text>
                <Text><strong>Skills:</strong> {rep.skills.join(', ')}</Text>
  
                <Divider my={3} />
                <Text fontWeight="bold">Deals:</Text>
                <List spacing={1} mb={3}>
                  {rep.deals.map((deal, idx) => (
                    <ListItem key={idx}>
                      {deal.client}: ${deal.value.toLocaleString()} ({deal.status})
                    </ListItem>
                  ))}
                </List>
  
                <Text fontWeight="bold">Clients:</Text>
                <List spacing={1}>
                  {rep.clients.map((client, idx) => (
                    <ListItem key={idx}>
                      {client.name} ({client.industry}) - {client.contact}
                    </ListItem>
                  ))}
                </List>
              </Box>
            ))}
          </VStack>
        )}
      </Box>
    )
  }
  